/* المرحلة ٦: الأعمدة تُرفع (١٨–٢١ سنة) — الجامعة والأمة · سيناريوهات كاملة */
window.SD.stages.push({id:6,icon:'🏗️',color:'#274060',name:'الأعمدةُ تُرفَع',years:'١٨–٢١ سنة',place:'الجامعة — وعواصم الأمة',
intro:'الفتى يصير رجلاً بمشروع: هندسة بنية «أبني للأمة»، حلقة جامعية من اثنتي عشرة جنسية، ماء للمخيم، منصة تصل مليون فتى، فتنة الشهرة، عرض الغرب المغري — وعودة إلى مانشستر تقطف أجمل ثمرة.',
eps:[
{n:77,t:'نيّةُ المهندس',ic:'🎓',age:'١٨ سنة',loc:'الجامعة — عمّان',corner:'academy',goal:'العلم بنية: التخصص عبادة إذا صحت النية — «إنما الأعمال بالنيات» في قاعة المحاضرات',chars:['صلاح الدين','زميل جامعي','أيوب','طلاب المجموعة'],
scenes:[
{h:'م١ · خارجي — حرم كلية الهندسة، أول يوم',d:'ممرات جامعية واسعة، لافتات تسجيل، آلاف الطلاب الجدد. صلاح الدين (١٨) بحقيبة ودفتر جديد، يقف أمام مبنى الهندسة ويتأمله كمن يقف على عتبة حلم كتبه في سجود ليلة القدر.',dlg:[['زميل جامعي','(بجانبه في طابور التسجيل، متحمس) أخيراً! الهندسة تذكرةُ الخروج! سنتخرج، نهاجر، ونتوظف براتبٍ بالدولار — تعرف كم يكسب المهندس في الخارج؟'],['صلاح الدين','(يبتسم بلا حكم) رزقٌ طيبٌ إن شاء الله. لكن… هل هذا كلُّ السبب؟ نتعلمُ لنغادر؟'],['زميل','(مستغرب) ولماذا غير هذا؟! الجميعُ يدرسُ ليكسب!']],vo:'وقفتُ على عتبةِ الحلمِ الذي كتبتُهُ في سجودِ ليلةِ القدر… وأولُ ما سمعتُهُ: «نتعلمُ لنغادر». أدركتُ يومَها أن أخطرَ سؤالٍ لطالبٍ ليس «ماذا تدرس؟»… بل «لماذا؟». فالعملُ الواحدُ يصعدُ أو يهبطُ بحسبِ النية.'},
{h:'م٢ · داخلي — غرفته، عقد النية',d:'الليل. صلاح الدين يفتح دفتر الجامعة الجديد على صفحته الأولى — كما فتح كل دفاتر عمره على عهد. يكتب بخط أنيق.',dlg:[['صلاح الدين','(يكتب ويقرأ) «عقدُ النية — أولُ يومٍ في الهندسة: أدرسُ لأبنيَ للأمةِ مدارسَها ومساجدَها وبيوتَ فقرائِها ومستشفياتِها. أتقنُ لأن اللهَ يحبُّ المتقن. والرزقُ الطيبُ نعمةٌ أقبلُها ولا أعبدُها. النيةُ أولاً… ثم المعادلات». (يعلق فوق مكتبه لوحة صغيرة: «إنما الأعمالُ بالنيات»)'],['أيوب','(يطرق، يرى ما كتب) عقدُ نيةٍ قبل أول محاضرة؟'],['صلاح الدين','درسُ العمرِ يا بابا: علّمتْني أمي أن أنويَ قبلَ الحفظ، والشيخُ أن أنويَ قبلَ الإمامة… فكيف أدخلُ أربعَ سنواتِ هندسةٍ بلا نية؟ الزميلُ اليومَ سيدرسُ ليهاجر… وأنا سأدرسُ نفسَ المعادلاتِ لأبنيَ لأمتي. نفسُ الجهد… وأجرٌ يفترقُ كالسماءِ عن الأرض.'],['أيوب','(يقبّل رأسه) بهذه النيةِ يا بني… تصيرُ كلُّ ليلةِ سهرٍ عبادة، وكلُّ مسألةٍ صعبةٍ جهاداً.']]},
{h:'م٣ · داخلي — قاعة المحاضرات، النية تعمل',d:'مونتاج الأسبوع الأول — النية ليست شعاراً بل سلوكاً: صلاح الدين يختار المقعد الأمامي (الطلاب يتزاحمون على الخلف)، يسأل الأستاذ بلا خجل، يدوّن بعناية. الأستاذ يلاحظه.',dlg:[['الأستاذ','(بعد المحاضرة) أنت من اختار المقعد الأول وسأل ثلاثة أسئلة… نادرٌ في السنة الأولى. لماذا هذا الحرص؟'],['صلاح الدين','لأني لا أجمعُ درجاتٍ يا دكتور… أجمعُ أدواتٍ لأبني بها. والذي يبني بيتاً لأمتِهِ… لا يغفو في محاضرةِ الأساسات.']]},
{h:'م٤ · داخلي — المكتبة، المجموعة المفتوحة',d:'صلاح الدين يؤسس مجموعة مذاكرة — ويعلن أنها مفتوحة للجميع، حتى المتعثرين. زميله الأول (الذي يريد الهجرة) يتعجب.',dlg:[['زميل','مجموعةٌ مفتوحةٌ للجميع؟ ستضيّعُ وقتَكَ على الضعاف! المجموعاتُ الذكيةُ مغلقةٌ ونخبوية.'],['صلاح الدين','قاعدتي من التوجيهي يا صاحبي: من علّمَ فهم مرتين، والقائدُ يرفعُ الجميع. ثم إني لا أدرسُ لنفسي وحدي… أدرسُ لأمة، والأمةُ لا تُبنى بنخبةٍ تصعدُ وتتركُ شعبَها خلفها. تعالَ اجلسْ معنا — ستفهمُ لماذا المجموعةُ المفتوحةُ أذكى من المغلقة.'],['زميل','(يجلس متردداً)… حسناً، لكن لا تقلْ إني لم أحذرْك من إضاعةِ الوقت. (بعد ساعة، وقد فهم درساً كان عالقاً) …أو ربما كنتَ محقاً.']]},
{h:'م٥ · داخلي — القاعة، خاطرة الختام',d:'نهاية اليوم الأول الحقيقي. القاعة تفرغ. صلاح الدين آخر من يخرج، يلتفت للمقاعد الفارغة والسبورة المليئة بالمعادلات.',dlg:[['صلاح الدين','(يهمس، يمر بيده على المقعد الأول)… نفسُ القاعة، ونفسُ المعادلات، ونفسُ الأربعِ سنين. الفرقُ كلُّهُ في سطرٍ كتبتُهُ الليلةَ في دفتري.']],vo:'جلستُ على نفسِ المقعدِ الذي جلسَ عليه من يدرسُ ليهاجر… لكنَّ قلبي كان يعرفُ وجهتَه. يا كلَّ طالبٍ يسمعُني: النيةُ لا تكلفُكَ دقيقةً واحدة، لكنها تحوّلُ أربعَ سنواتِ تعبٍ إلى أربعِ سنواتِ عبادة. اكتبْ عقدَ نيتِك… قبل أن تكتبَ أولَ معادلة.'}],
msg:'إنما الأعمال بالنيات: نفس الجهد ونفس المعادلات — لكن من تعلّم ليبني لأمته صار كل سهره عبادة، ومن تعلّم لنفسه فقط ربح الدنيا وحدها.',apply:'اكتب «عقد نيتك» لدراستك في أول صفحة من دفترك: لماذا تتعلم؟ لمن؟ — وجدده كل فصل.'},

{n:78,t:'حلقةُ الاثنتي عشرةَ جنسية',ic:'🌍',age:'١٨ سنة',loc:'مسجد الجامعة',corner:'quds',goal:'الأمة الواحدة رأي العين: الجامعة مصغر العالم الإسلامي — والاختلاف غنى لا فرقة',chars:['صلاح الدين','طلاب من جنسيات','رحمت (إندونيسي)','آدم (بوسني)','عبد الرحمن (صومالي)'],
scenes:[
{h:'م١ · داخلي — مسجد الجامعة، اكتشاف المهجور',d:'مسجد جامعي صغير، مهجور بين الصلوات — سجاد باهت وركن مصاحف مغبر. صلاح الدين يصلي فيه الفجر وحده تقريباً، ينظر حوله ويقرر.',dlg:[['صلاح الدين','(لنفسه) مسجدٌ في قلبِ جامعةٍ فيها آلافُ الطلاب… فارغٌ بين الصلوات؟ (يفتح دفتره) بيوتُ اللهِ لا تُترَكُ خاوية. حلقةُ فجرٍ… تبدأ من الغد.']],vo:'في مانشستر أحيا الشيخُ إدريسُ مسجداً صغيراً فآواني غريباً. واليومَ جاءَ دوري: مسجدٌ جامعيٌّ مهجور، وقرارٌ بإحيائِه. لم أكن أعرفُ أني على وشكِ أن أرى الأمةَ كلَّها… تتجمعُ في غرفةٍ واحدة.'},
{h:'م٢ · داخلي — المسجد، توافد الجنسيات',d:'مونتاج شهرين: يبدأ صلاح الدين وحده ثم اثنان ثم خمسة. وجوه من كل العالم الإسلامي تتوافد — تُعلَّق خريطة عالم على الجدار ويُغرَز دبوس لكل عضو.',dlg:[['رحمت (إندونيسي)','(بعربية بلكنة) سمعتُ حلقةَ فجرٍ… في إندونيسيا نصلي الفجرَ والمسجدُ ملآن! هنا وجدتُ بيتي.'],['آدم (بوسني)','(يضع دبوسه على البوسنة) أنا من سراييفو… جدي نجا من الحرب. علّمني ألا أترك المسجد أبداً.'],['عبد الرحمن (صومالي)','(بابتسامة واسعة) والصومال هنا أيضاً! يا جماعة، صرنا أمماً في غرفة!'],['صلاح الدين','(ينظر للخريطة المرصعة بالدبابيس) اثنتا عشرةَ جنسية… في مسجدٍ واحدٍ صغير. نقرأُ بلكناتٍ شتى… ونحفظُ الحروفَ نفسَها. سبحان الله!']]},
{h:'م٣ · داخلي — المسجد، سفير الأسبوع',d:'صلاح الدين يبتكر تقليداً: كل جمعة يحكي طالب عن بلاده. مشهد آدم البوسني يحكي.',dlg:[['آدم','(بصوت يتهدج) في سراييفو، خلال الحرب، كان الناسُ يخرجون للصلاةِ تحت القصف… ماتَ إمامُ مسجدِنا وهو يؤذّن. جدتي تقول: ما انقطعَ الأذانُ يوماً واحداً في أصعبِ سنوات الحصار. حين تشتكون من برد الفجرِ… تذكروا من أذّنوا تحت الرصاص.'],['الحلقة','(صمت مؤثر… ثم دعاء جماعي للبوسنة)'],['صلاح الدين','(متأثراً) هذا يا إخوتي معنى «سفير الأسبوع»: لا نتعلمُ جغرافيا… نكتشفُ أننا جسدٌ واحد. إذا اشتكى منه عضو…'],['عبد الرحمن','(يكمل) تداعى له سائرُ الجسدِ بالسهرِ والحمى!']]},
{h:'م٤ · داخلي — المسجد، القدس قضية الجميع',d:'جمعة يتحدث فيها صلاح الدين عن القدس. يفاجئه رد الفعل.',dlg:[['صلاح الدين','أحدثكم عن قضيتي الأولى: القدس. وأعرف أنها قد تبدو «قضيةً عربية» بالنسبة لكم…'],['رحمت (الإندونيسي)','(يقاطع بحماس) عربية؟! يا أخي، في إندونيسيا — أبعدِ نقطةٍ عنكم — يخرجُ الملايينُ لأجلِ الأقصى! القدسُ في قلبِ كلِّ مسلمٍ من جاكرتا إلى المغرب — إنها أولى القبلتين، لا قبلةَ العربِ وحدَهم!'],['آدم','وفي البوسنة ندعو لها في كلِّ خطبة!'],['صلاح الدين','(يتأثر بعمق) سامحوني… أنا من ظننتُ خطأً أنها قضيتُنا وحدَنا. أنتم علّمتُموني اليومَ درساً: الأقصى ليس قضيةَ شعب… إنه قلبُ الأمةِ كلِّها. جيلُ القدسِ الذي أحلمُ به… يجب أن يكونَ بكلِّ هذه الألوان.']]},
{h:'م٥ · داخلي — المسجد، درس المشهد',d:'لقطة ختامية: الحلقة بعد الفجر، اثنا عشر وجهاً من اثنتي عشرة أمة، يقرؤون آية واحدة بصوت واحد رغم اللكنات، والخريطة خلفهم مرصعة بالدبابيس.',dlg:[['صلاح الدين','(للحلقة) انظروا حولكم… هذا هو مسجدُ الجامعةِ الذي ظننتُهُ مهجوراً. صار مصغَّرَ العالمِ الإسلامي. في مانشستر رأيتُ هذا المشهدَ طفلاً في إفطارِ رمضان — ألواناً تجمعُها تمرة. واليومَ أراهُ رجلاً — أمماً يجمعُها مصحف. ولو اجتمعتْ هذه الأمةُ حقاً كما تجتمعُ في هذه الغرفة… لتغيّرَ وجهُ الأرض.']],vo:'اثنتا عشرةَ جنسيةً في غرفةٍ واحدة… أرَتْني بعيني ما كنتُ أقرؤه: أن هذه الأمةَ عملاقٌ نائمٌ فرّقتْهُ الحدود. لكنه إن استيقظَ… فالأرضُ كلُّها لا تتسعُ لهمّتِه. اعرفوا إخوانَكم في كلِّ بلدٍ يا شباب… فالوحدةُ تبدأ بأن نعرفَ أننا واحد.'}],
msg:'الأمة جسد واحد فرّقته الحدود: القدس قلب كل مسلم من جاكرتا إلى المغرب لا قضية شعب — والاختلاف في اللكنات غنى، والمصحف يجمع.',apply:'تعرف هذا الشهر على مسلم من بلد مختلف عنك (في الواقع أو عبر أهلك) — واسأله: كيف يعيش المسلمون عندكم؟'},

{n:79,t:'ماءٌ للمخيم',ic:'🚰',age:'١٩ سنة',loc:'المخيم — قرب عمّان',corner:'academy',goal:'الهندسة تسجد لله: أول مشروع حقيقي يخدم الناس — العلم الذي لا ينفع كنز مدفون',chars:['صلاح الدين','كريم','الأستاذ المشرف','فريق الهندسة','أم فايز'],
scenes:[
{h:'م١ · داخلي — قاعة الهندسة، قلب المشروع',d:'الأستاذ يكلف الطلاب بمشروع مادة الهندسة المدنية: تصميم نظري لشبكة مياه. الطلاب يفكرون في نماذج ورقية. صلاح الدين يرفع يده باقتراح مختلف.',dlg:[['صلاح الدين','دكتور… بدل تصميمٍ نظريٍّ يُرمى بعد التقييم، هل نأخذُ مشكلةً حقيقية؟ حارةُ صديقي كريم في المخيم ينقطعُ عنها الماءُ ثلاثةَ أيامٍ في الأسبوع منذ سنين. نصممُ لهم حلاً… وننفذُه.'],['الأستاذ','(مندهش) تنفذونه فعلاً؟ هذا يتجاوزُ المطلوب بكثير — عملٌ وميزانيةٌ وميدان…'],['صلاح الدين','العلمُ الذي لا يُنفَّذُ يا دكتور… كنزٌ مدفون. وأنا كتبتُ في أول دفتري: أدرسُ لأبني. فلأبدأ الآن — لا بعد التخرج.'],['الأستاذ','(يبتسم) موافق. وسأشرفُ عليه بنفسي — هذا النوعُ من الطلابِ نادر.']]},
{h:'م٢ · خارجي — المخيم، الهندسة تلبس حذاء الميدان',d:'صلاح الدين وفريقه في أزقة المخيم مع كريم — مسح ميداني: قياسات، مقابلات مع الأهالي، رسم الشبكة القديمة المتهالكة. الهندسة تخرج من القاعة إلى الواقع الطيني.',dlg:[['كريم','(يقودهم) هنا الخزانُ القديم — جافٌّ منذ سنين. والناسُ يشترون الماءَ بالصهاريج بأضعافِ سعرِه، أو ينتظرون ساعاتٍ عند الصنبورِ العام.'],['صلاح الدين','(يقيس ويرسم) إذن الحلُّ ليس معقداً هندسياً: خزانٌ علويٌّ بمضخةٍ شمسيةٍ، وشبكةُ مواسيرَ توزّعُ بالجاذبية. الكلفة معقولة… والتمويلُ من صندوقِ جيلِ القدسِ وحملةٍ صغيرة. (لفريقه) رأيتم؟ المشكلةُ التي عاشها الناسُ سنين… حلُّها في متناولِ طلابِ سنةٍ ثانية. فقط احتاجت من ينزلُ من القاعةِ إلى الزقاق.']]},
{h:'م٣ · خارجي — المخيم، كارثة الوصلة',d:'التنفيذ. أول اختبار للشبكة — وصلة رئيسية تنفجر تحت الضغط فيغرق زقاق بالماء أمام الأهالي المتجمعين. إحراج. بعض الأهالي يتذمرون: «طلابٌ يجرّبون علينا!».',dlg:[['رجل من الأهالي','(غاضباً) قلنا لكم! صغارٌ يلعبون بالمواسير ويغرقون حارتَنا!'],['صلاح الدين','(لا يبرر ولا ينكسر — يخوض الماء بنفسه ويغلق المحبس) معك حق يا عمي، وأنا آسف — الخطأُ خطؤنا لا خطؤك. حسبنا الضغطَ خطأً عند هذه الوصلة. (لفريقه بهدوء) لا نلومُ المواسير… نلومُ حساباتِنا. أعيدوا الحساب — والتواضعُ أمام الخطأِ أولُ الهندسةِ الصحيحة. سنصلحُها الليلةَ ونعتذرُ بالعمل لا بالكلام.'],['الأستاذ','(يراقب، يهمس لنفسه) يتحملُ الخطأَ أمام الناسِ بلا تبرير… هذا مهندسٌ حقيقيٌّ قبل أن يتخرج.']]},
{h:'م٤ · خارجي — المخيم، مونتاج الإنجاز',d:'مونتاج: إصلاح الحسابات، الأهالي أنفسهم ينضمون للعمل (تحول من التذمر إلى الشراكة)، تركيب الألواح الشمسية، اختبار ناجح للضغط. الأطفال يتجمعون بفضول حول الخزان الجديد.',dlg:[['كريم','(متحمس) الضغطُ مثاليٌّ في كل النقاط! نجحت!'],['الرجل الذي تذمر','(الآن يعمل معهم، محرج) سامحني على كلامي يومَها يا بني… ظننتُكم تلعبون. أنتم… بنيتُم لنا ما عجزتْ عنه جهاتٌ كبيرة.'],['صلاح الدين','(يصافحه بحرارة) بل شكراً لك — نزولُكَ للعملِ معنا هو ما أنجزها. الماءُ لكم… وأنتم من يصونُهُ بعدنا.']]},
{h:'م٥ · خارجي — المخيم، دعاء أم فايز',d:'يوم الافتتاح. الصنبور الأول في بيت أم فايز — عجوز أرملة كانت تحمل الماء على رأسها من بعيد. تفتح الصنبور فيتدفق الماء. تبكي وترفع يديها.',dlg:[['أم فايز','(ترفع يديها المرتجفتين للسماء) يا رب… سبعُ سنينَ أحملُ الماءَ على رأسي وظهري ينحني. اللهم يا من أرسلتَ هؤلاءِ الأولاد… ارزقهم من حيثُ لا يحتسبون، واحفظهم كما حفظوا كرامتي، وافتح لهم أبوابَ الخيرِ كما فتحوا لي بابَ الماء. (لصلاح الدين) يا بني… دعوةُ عجوزٍ في جوفِ الليلِ لا تُرَد.'],['صلاح الدين','(يتأثر بعمق، يقبّل رأسها) دعاؤكِ يا خالتي… أثقلُ في ميزاني من كلِّ درجاتِ الهندسة.']],vo:'صمم فريقُنا شبكةً بعشراتِ الحسابات… وكانت أثمنَ نتيجةٍ فيها: دعوةَ عجوزٍ رفعتْ يديها عند صنبورِ ماء. تلك الدعوةُ — لا الدرجةُ التي أخذناها — هي شهادتي الحقيقية. يا طلابَ العلم: علمُكم أمانة، ونفعُ الناسِ به عبادة. لا تدفنوا كنوزَكم في أوراقِ الامتحانات… أخرجوها إلى الأزقةِ التي تنتظرُها.'}],
msg:'العلم الذي لا ينفع كنز مدفون: الهندسة تسجد لله حين تخدم الناس — ودعوة عجوز عند صنبور ماء أثقل من كل الدرجات.',apply:'حوّل واجبك القادم إلى نفع حقيقي: قدّم بحثك أو مشروعك عن مشكلة يعانيها حيّك — واقترح حلاً قابلاً للتنفيذ.'},

{n:80,t:'منصةُ الجيل',ic:'📱',age:'١٩ سنة',loc:'غرفة السطح — المقر',corner:'academy',goal:'الإعلام الهادف صناعة: من حساب صغير إلى منصة أمة — المحتوى النظيف يفوز إذا أتقن',chars:['صلاح الدين','معاذ','حمزة','كريم','شام'],
scenes:[
{h:'م١ · داخلي — مقر جيل القدس، الحاجة تولد الفكرة',d:'لقاء جيل القدس الأسبوعي. فتيان كثر يسألون سؤالاً متكرراً.',dlg:[['فتى','أستاذ صلاح الدين، حلقةُ الخميسِ لا تكفينا! ألا يمكنُ أن نراها مصورةً نعيدُها في البيت؟ أصدقائي في مدنٍ أخرى يريدون الانضمامَ ولا يستطيعون الحضور.'],['صلاح الدين','(يلتفت للعصبة) سمعتم؟ الحاجةُ تطرقُ البابَ بنفسِها. عهدُ الهاتفِ علّمني: الشاشةُ سكينٌ — والآن نصنعُ بها خبزاً لآلافٍ لا يصلوننا. ما رأيكم بمنصة؟'],['معاذ','فكرةٌ عظيمة… لكن الإنترنت مليءٌ بالغثِّ يا صلاح الدين. كيف نتميز؟'],['صلاح الدين','بالإتقانِ والصدق. المحتوى النظيفُ المتقن يفوز — الناسُ عطشى للطيبِ وسط الغثاء.']]},
{h:'م٢ · داخلي — المقر، ميثاق المحتوى',d:'قبل أول فيديو، صلاح الدين يصر على كتابة ميثاق على الجدار — كعادته: القواعد قبل العمل.',dlg:[['صلاح الدين','(يكتب على لوحة) ميثاقُ منصةِ جيل القدس، قبل أن نصوّرَ ثانيةً واحدة: أولاً — لا كذبَ ولا مبالغة، ولو خسرنا مشاهدات. ثانياً — كلُّ معلومةٍ موثقةٌ من مصدرِها. ثالثاً — لا تنمرَ ولا سخريةَ من أحد. رابعاً — لا نستجدي الانتشارَ بالإثارةِ الرخيصة. خامساً — النيةُ تُراجَعُ جماعياً كلَّ شهر.'],['حمزة','قواعدُ صارمة! ألن تبطئنا عن المنافسة؟'],['صلاح الدين','ستبطئُنا في البدايةِ يا حمزة… وتبقينا حين يسقطُ غيرُنا. المحتوى المبنيُّ على الكذبِ والإثارةِ كبيتِ العنكبوت — يعلو بسرعةٍ وينهارُ بسرعة. نحن نبني حجراً حجراً… لنبقى.']]},
{h:'م٣ · داخلي — السطح، الاستوديو المرتجل',d:'مونتاج ممتع لبناء استوديو بسيط على السطح: بطانيات معلقة للعزل الصوتي، مصباحان للإضاءة، هاتف على حامل خشبي صنعه أبو خليل النجار. فريق التخصصات يتوزع: معاذ للمونتاج، حمزة للتصوير، كريم يكتب القصص، وشام (كبرت — ١٢ سنة) تدير ركن البنات بحماس.',dlg:[['شام','(بحماس) وأنا سأصوّرُ قصصَ الصغيرات مثل ماما كانت تحكي لكم! ركنُ البناتِ لن يكون ناقصاً!'],['صلاح الدين','(يبتسم) بل هو نصفُ المنصةِ يا شام — أمي علّمتني أن الأمهاتِ هنَّ الحلقاتُ الأولى. اصنعي جيلَ الأمهاتِ القادمات.'],['معاذ','(خلف الكاميرا) جاهزون؟ أول فيديو: صلاح الدين، احكِ لهم لعبةَ «من صنعها؟» — تلك التي علّمكَ إياها أبوك.']]},
{h:'م٤ · داخلي — المقر، أول انتشار',d:'أول فيديو («من صنعها؟» للأطفال) يُنشر. الفريق يراقب الأرقام. تعليقات تتوافد من مدن بعيدة.',dlg:[['كريم','(يقرأ التعليقات مذهولاً) تعليقٌ من جدة… من كوالالمبور… أمٌّ تقول: علّمتُ ابني اللعبةَ وبكيتُ! معلمةٌ من نيجيريا تطلبُ الإذنَ لعرضِهِ في صفها!'],['صلاح الدين','(متأثر) اللعبةُ التي علّمنيها أبي في حديقةِ مانشستر وأنا في الرابعة… تصلُ اليومَ لطفلٍ في نيجيريا. سبحان الله — بذرةٌ واحدةٌ صادقة، أين تصلُ حين نسقيها بالإتقان.']]},
{h:'م٥ · داخلي — المقر، لوحة المئة ألف',d:'بعد سنة. الفريق أمام الشاشة: العداد يبلغ مئة ألف متابع. لكن صلاح الدين لا يدعهم ينتشون — يقود تجديد نية جماعياً.',dlg:[['حمزة','مئةُ ألف! نحتفل؟'],['صلاح الدين','نسجدُ شكراً أولاً… ثم نجدد النية. (يجمعهم) اسمعوا — هذا الرقمُ خطرٌ كما هو نعمة. مئةُ ألفٍ يعني مئةَ ألفِ أمانةٍ في أعناقِنا، لا مئةَ ألفِ سببٍ للغرور. من الآن نضاعفُ الحذر: كلما كبرَ المنبرُ… ثقُلَتِ الكلمة. أعيدوا معي عهدَ النية: نصنعُ لله، لا للأرقام؛ وننفعُ الأمة، لا نُطربُها.'],['الفريق','(معاً) لله لا للأرقام.'],['شام','(تكتب على اللوحة تحت الرقم) «مئةُ ألفِ أمانة».']],vo:'مئةُ ألفٍ في سنة… ونحن نصورُ ببطانياتٍ ومصباحين على سطحِ بيتِ جدي. تعلمتُ أن المحتوى النظيفَ المتقنَ يشقُّ طريقَهُ وسط بحرِ الغثاء — لأن الناسَ في قرارةِ قلوبِهم عطشى للطيب. يا شبابَ زماني: لا تتركوا الميدانَ الرقميَّ للتافهين… ادخلوه بإتقانٍ وصدق، واصنعوا فيه نوراً. الشاشةُ مرآةُ من يمسكُها.'}],
msg:'المحتوى النظيف المتقن يفوز لأن الناس عطشى للطيب: الشاشة سكين تصنع بها خبزاً — والقواعد قبل العمل، والنية تُراجَع كلما كبر المنبر.',apply:'قبل أن تنشر أي شيء اليوم اسأل: هل ينفع؟ هل هو صدق؟ هل أرضاه لله؟ — وشارك اليوم محتوى نافعاً واحداً بدل عشرة تافهة.'},

{n:81,t:'فتنةُ المليون',ic:'🪞',age:'١٩ سنة ونصف',loc:'عمّان',corner:'heart',goal:'الإخلاص تحت الأضواء: الشهرة امتحان أخطر من الفقر — علاج الرياء عملياً',chars:['صلاح الدين','الشيخ محمود','فاطمة (لاحقاً)','معاذ'],
scenes:[
{h:'م١ · داخلي — المقر، الصعود',d:'مونتاج سريع: العداد يتجاوز المليون. مقابلات تلفزيونية، دعوات لمؤتمرات، وجهه على لافتات، طلاب يوقفونه في الجامعة لصورة. الأضواء تقترب.',vo:'واجهتُ في طفولتي فتنةَ الفقرِ والحاجةِ فصبرت. وواجهتُ فتنةَ السخريةِ فثبتُّ. لكنَّ أخطرَ فتنةٍ في حياتي جاءتني في ثوبِ نعمة: الشهرة. المليون. الأضواء. فتنةٌ لا تؤلمُ كالفقر… بل تُدغدغُ حتى تُهلك.'},
{h:'م٢ · داخلي — المقر، اللحظات الكاشفة',d:'مشاهد صغيرة كاشفة: صلاح الدين يلقي كلمة ثم — بدل مراجعة قلبه — يفتح الهاتف يعد الإعجابات. فيديو «لم ينتشر» فيحزن حزناً حقيقياً — أعمق من حزنه حين تأخر ورده أمس. معاذ يلاحظ التغير الخفي.',dlg:[['معاذ','(بصراحة الأخ) لاحظتُ شيئاً… صرتَ تسألُ عن أرقامِ الفيديو قبل أن تسألَ هل نفع. وحزنتَ أمسِ لفيديو «ضعيف» أكثرَ مما حزنتَ لفواتِ سنةِ الفجر. هل أنا مخطئ؟'],['صلاح الدين','(يصمت… الكلمة تصيبه) …لا. لستَ مخطئاً. (يجلس مثقلاً) متى تغيرتُ يا معاذ؟']]},
{h:'م٣ · داخلي — مكان صدقة، المشهد الكاشف',d:'قمة درامية صامتة: صلاح الدين يعطي صدقة لمحتاج في الشارع — ثم يجد يده تلقائياً تمتد لهاتفه ليصوّر «اللحظة الملهمة للمتابعين». يتجمد. ينظر لهاتفه… ولوجه المحتاج… ويسحب يده كأنها لُسِعت. يمشي بعيداً مصدوماً من نفسه.',dlg:[['صلاح الدين','(يتكئ على جدار، يتنفس بصعوبة) كدتُ… كدتُ أصوّرُ صدقة! أُشهِدُ عليها مليوناً بدل أن أُخفيها عن الملَكين! يا الله… إلى أين انزلقتُ؟ (يخرج هاتفه، يتصل) الشيخ محمود… أحتاجُ أن أراك. أخافُ… أخافُ أني صرتُ أعملُ للكاميرا.']]},
{h:'م٤ · داخلي — بيت الشيخ محمود، المصارحة',d:'الشيخ محمود — طاعن في السن الآن — يستقبله. صلاح الدين يفرغ خوفه.',dlg:[['الشيخ محمود','(يستمع ثم يبتسم بهدوء مطمئن) اسمعْ يا بني بشارةً قبل الموعظة: سؤالُ الرياءِ الذي جئتَ تسألُه… لا يسألُهُ المراؤون! المرائي منتفخٌ راضٍ عن نفسِه. أما من يخافُ الرياءَ ويجيءُ يبكي منه… فهذا قلبٌ حيٌّ دقَّ ناقوسَه. خوفُكَ هذا نصفُ العلاج.'],['صلاح الدين','والنصفُ الآخر؟'],['الشيخ محمود','ثلاثةُ أدوية عملية، لا مواعظ: أولاً — بابٌ خلفيٌّ من الأعمالِ السرية: عبادةٌ وصدقةٌ يوميةٌ لا يعلمُها إلا الله، توازنُ بها علانيتَك. ثانياً — صحبةٌ تجرؤُ على نقدِك، كما فعلَ معاذ اليوم — احتفظْ بهم فهم مرآتُك. ثالثاً — دعاءٌ لا تتركُه: اللهم اجعل عملي كلَّه صالحاً، واجعلْهُ لوجهِكَ خالصاً، ولا تجعلْ لأحدٍ فيه شيئاً. الشهرةُ يا بني ليست حراماً… لكنها نارٌ: تدفئُ من ضبطَها، وتحرقُ من نامَ بجانبِها.']]},
{h:'م٥ · داخلي — غرفته، الباب الخلفي',d:'صلاح الدين في غرفته ليلاً، يفتح دفتره ويكتب برنامج العلاج. مونتاج قصير للتطبيق: يصلي ركعتين في جوف الليل لا يعلمهما أحد، يضع صدقة في يد محتاج ويمضي بلا تصوير، يحذف بعض المنشورات التي شعر أن فيها استعراضاً.',dlg:[['صلاح الدين','(يكتب) «برنامجُ حراسةِ القلب: عملٌ سريٌّ يوميٌّ لا أذكرُهُ لأحدٍ أبداً. أطلبُ من معاذ أن ينتقدَني بصراحةٍ كلَّ أسبوع. دعاءُ الإخلاصِ بعد كلِّ ظهور. وأسألُ نفسي قبل كلِّ فيديو: لو لم يرَهُ أحد… هل كنتُ سأصنعُه؟». (يغلق الدفتر) الميدانُ الرقميُّ لن أتركَه… لكني سأدخلُهُ بقلبٍ محروس.'],['معاذ','(عبر الهاتف) وأنا وافقتُ أن أكونَ «مرآتَك القاسية»… بشرطِ أن تتحملَ صراحتي!'],['صلاح الدين','(يضحك) بل هذا أعظمُ خدمةٍ تقدمُها لي يا معاذ — الصديقُ الذي يجاملُك في دينِك… ليس صديقاً.']],vo:'الشهرةُ يا أصدقائي أخطرُ من الفقرِ بكثير: الفقرُ يؤلمُكَ فتلجأُ لله، والشهرةُ تدغدغُكَ فتنسى الله. نجوتُ منها بثلاثة: عملٍ سريٍّ يوازنُ علانيتي، وصديقٍ يجرؤُ على نقدي، ودعاءٍ لا يفتر. فإن رزقكَ اللهُ يوماً منبراً أو أضواء… فابنِ لنفسِكَ باباً خلفياً من الأعمالِ التي لا يراها إلا الله. فهو وحدَهُ الذي يزنُ القلوب.'}],
msg:'الشهرة نار تدفئ من ضبطها وتحرق من نام بجانبها: خوفك من الرياء نصف علاجه — فابنِ باباً خلفياً من العمل السري، واحتفظ بصديق يجرؤ على نقدك.',apply:'ابدأ «عملك السري»: عبادة أو صدقة يومية صغيرة لا يعلمها أحد غير الله — ولا تحدث بها أبداً.'},

{n:82,t:'عرضُ الذهبِ الغربي',ic:'⚖️',age:'٢٠ سنة',loc:'الجامعة والبيت',corner:'heart',goal:'الثبات أمام الإغراء الكبير: القرار بالاستشارة والاستخارة — والرسالة تسبق الراتب',chars:['صلاح الدين','أيوب','مريم','الشيخ محمود','ممثل الشركة'],
scenes:[
{h:'م١ · داخلي — الجامعة، العرض',d:'مكتب عميد الكلية. ممثل شركة عالمية يقدم عرضاً لصلاح الدين المتفوق: منحة كاملة لإكمال الدراسات العليا في الخارج، وعقد عمل بعدها براتب خيالي.',dlg:[['ممثل الشركة','أنت من أوائل دفعتك، ومشروعُك في الطاقةِ الشمسيةِ لفتَ انتباهنا. نعرضُ عليك: ماجستيرٌ ودكتوراهٌ بمنحةٍ كاملة، ثم عقدٌ براتبٍ من ستةِ أرقام. مستقبلٌ لا يحلمُ به أحد. الشرطُ الوحيد: تفرغٌ كامل — تترك «أنشطتَك الجانبية» كلَّها. المنصة، النادي… هذه لن تناسبَ جدولَ باحثٍ عالمي.'],['صلاح الدين','(يمسك الورقة… عينه تلمع لحظة ثم تنطفئ عند كلمة «تترك أنشطتك») …أشكرُك من قلبي على الثقة. أعطني أسبوعاً — قرارٌ بهذا الحجمِ لا يُتخذُ في غرفة.']],vo:'عرضٌ يحلمُ به كلُّ شاب: مستقبلٌ مضمونٌ وراتبٌ خياليٌّ وعلمٌ في أرقى الجامعات. والغربُ يا أصدقائي ليس شراً، والسفرُ للعلمِ ليس خيانة — علماؤنا رحلوا لطلبِ العلمِ شهوراً على ظهورِ الإبل. لكنَّ الشرطَ الصغيرَ في آخرِ العرض — «تترك أنشطتك» — كان في الحقيقةِ يقول: اترك رسالتَك. وهنا كان الميزان.'},
{h:'م٢ · داخلي — البيت، مجلس الاستشارة',d:'مجلس عائلي — كما في قرار الهجرة قديماً. صلاح الدين يعرض، وأيوب (الذي عاش الغربة) يتكلم بإنصاف.',dlg:[['صلاح الدين','بابا، أنتَ عشتَ الغربة… أنصحُني بصدق: أذهب؟'],['أيوب','لن أقررَ عنك — أنتَ رجلٌ الآن، عندك عقلٌ يزنُ ومنهجٌ يقرر. لكني أعطيكَ خبرتي بإنصاف: العلمُ في الخارجِ نعمةٌ حقيقية، والمالُ يفتحُ أبواباً للخير. لكنِ اسأل نفسك سؤالاً واحداً: العرضُ يطلبُ منكَ أن «تترك». تترك ماذا؟ المنصةَ التي تصلُ مليوناً، وجيلَ القدسِ في أربعين بلداً، وقافلةَ البناء. أتوجدُ منحةٌ في الأرضِ تعوّضُ عن رسالةِ حياتِك؟'],['مريم','والسؤالُ الأعمق: هل تستطيعُ أن تحققَ رسالتَكَ بطريقٍ آخرَ لا يطلبُ منك تركَها؟ لا ترفضِ العلمَ… ارفضِ الشرطَ الذي يقتلُ رسالتَك.']]},
{h:'م٣ · داخلي — بيت الشيخ، والمسجد',d:'صلاح الدين يستشير الشيخ محمود ثم يصلي الاستخارة ليالي.',dlg:[['الشيخ محمود','القاعدةُ يا بني: الرسالةُ تسبقُ الراتب. لكن لا تجعلْها عاطفة — استخرِ اللهَ واستشرِ العقلاء، وقد فعلت. والاستخارةُ لا تنتظرْ منها حلماً؛ انتظرْ منها انشراحاً يُبنى بالعقلِ والدعاءِ معاً.'],['صلاح الدين','(في سجود الاستخارة) اللهم إن كان هذا العرضُ خيراً لديني ورسالتي فيسّرْه، وإن كان يصرفُني عما خلقتَني له فاصرفْهُ عني واصرفني عنه، واقدُرْ لي الخيرَ حيث كان ثم رضّني به.']]},
{h:'م٤ · داخلي — مكتب الشركة، الرد',d:'صلاح الدين يعود بردّ — احترافي، هادئ، واثق. لا شعارات.',dlg:[['صلاح الدين','فكرتُ واستشرتُ واستخرت. جوابي: أشكرُكم على تقديرٍ يشرفُني — وأعتذرُ عن الشرط، لا عن العلم. لن أتركَ مشروعَ حياتي مقابلَ أيِّ راتب. لكن — (يخرج ورقة أعدها) عندي بديلٌ أعرضُهُ عليكم: شراكةٌ بحثيةٌ عن بُعد. أُكملُ دراساتي العليا من هنا بإشرافِكم، وأعملُ على مشاريعِكم في الطاقةِ الشمسيةِ من مقري، وأبقى على أرضي ومع رسالتي. أنتم تكسبون عقلاً، وأنا أكسبُ علماً بلا أن أخونَ عهدي. ما رأيكم؟'],['ممثل الشركة','(مندهش، يقرأ الورقة) شابٌّ يرفضُ عرضَنا… ثم يعرضُ علينا عرضاً أذكى؟ (يبتسم) هذا النوعُ من العقولِ هو ما نريده أصلاً. سأرفعُ اقتراحَك — وأظنهم سيقبلون.']]},
{h:'م٥ · داخلي — البيت، قلب الطاولة',d:'بعد أسابيع: رسالة قبول من الشركة بشرط صلاح الدين هو. العائلة تحتفل باعتدال.',dlg:[['صلاح الدين','(يقرأ الرسالة) قبلوا! دراساتٌ عليا وشراكةٌ بحثية… من هنا، بلا أن أتركَ شيئاً. من ثبتَ على مبدئِه… رفعَ اللهُ قدرَه.'],['أيوب','(فخوراً) أتعرفُ الدرسَ الأعمق يا بني؟ حين تكونُ رسالتُكَ أوضحَ من طمعِك، وثباتُكَ أقوى من إغرائهم… ينحني لكَ من أردتَ أن تنحنيَ له. لم تفاوضْ من موقعِ محتاج… فاوضتَ من موقعِ صاحبِ رسالة.'],['صلاح الدين','ولو قبلتُ الشرطَ وتركتُ كلَّ شيء… لربحتُ راتباً وخسرتُ نفسي. والمالُ يا بابا يُكتَسَبُ ويُنفَق… أما الرسالةُ فإن بعتَها مرة… لا تُشترى ثانية.']],vo:'رفضتُ الشرطَ لا العلم… فأعطاني اللهُ العلمَ بلا شرط. تعلمتُ أن الثباتَ على المبدأِ لا يُفقرُك — بل يرفعُ قدرَك حتى عند من أردتَ أن تساومَك. يا شبابَ زماني: ستأتيكم عروضٌ لامعةٌ ثمنُها رسالتُكم. فاحفظوا المعادلة: استشيروا، واستخيروا، وقدّموا الرسالةَ على الراتب. الرسالةُ إذا بيعتْ مرة… لا تُشترى أبداً.'}],
msg:'الرسالة تسبق الراتب: من ثبت على مبدئه رفع الله قدره حتى عند خصمه — والمال يُكتسب ويُنفق، أما الرسالة فإن بعتها مرة لا تُشترى ثانية.',apply:'تعلّم معادلة القرار: استشر عاقلين خبيرين + استخر ركعتين + قدّم رسالتك على راتبك — وطبقها في قرارك القادم.'},

{n:83,t:'مؤتمرُ شبابِ الأمة',ic:'🕊️',age:'٢٠ سنة',loc:'إسطنبول — مؤتمر شبابي',corner:'quds',goal:'التشبيك لا التصفيق: العمل للأمة يحتاج جسوراً بين المخلصين — والوحدة صناعة صبورة',chars:['صلاح الدين','شباب من ٥٠ بلداً','منظم المؤتمر','قادة مشاريع'],
scenes:[
{h:'م١ · داخلي — بهو المؤتمر، إسطنبول',d:'قاعة فخمة، لافتة «مؤتمر شباب الأمة»، ثلاثمئة شاب من خمسين بلداً بأزياء وألسنة شتى. صلاح الدين — ممثل منصته — يدخل متحمساً للكلمات والخطب.',dlg:[['صلاح الدين','(لنفسه، متأملاً الحشد) ثلاثمئة قائدِ مشروعٍ من العالم كله في قاعةٍ واحدة! إن اتحدت طاقاتُهم… لأناروا الأمة. (يفتح دفتره) لنرَ ماذا سيخرجُ من هذا الاجتماع.']],vo:'ذهبتُ إلى إسطنبولَ أنتظرُ خطباً حماسيةً تشعلُ الأمة. ووجدتُ داءً قديماً جداً — الداءَ نفسَهُ الذي حكاهُ لي أبي عن زمنِ ما قبلِ صلاحِ الدين الأيوبي: طاقاتٌ عظيمة… لكنها جزرٌ معزولة، وخلافاتٌ صغيرةٌ تأكلُ الطاقات.'},
{h:'م٢ · داخلي — جلسة المؤتمر، صدمة الخلافات',d:'جلسة حوارية تنحرف: قادة مشاريع يتجادلون حول أمور هامشية — منهجيات، أساليب، حساسيات قديمة. النقاش يحتد على مسألة فرعية بينما القضايا الكبرى تنتظر.',dlg:[['قائد مشروع أول','منهجُنا هو الصحيح! أنتم تبدؤون من الإعلامِ ونحن من التعليم!'],['قائد مشروع ثانٍ','بل الإغاثةُ أولاً! ما نفعُ تعليمِ جائع؟!'],['صلاح الدين','(يراقب بحزن، يهمس لجاره) انظر… ثلاثمئةُ مخلصٍ يتقاتلون على «من يبدأ» بينما الأمةُ تنزف. كلُّهم على حق… وكلُّهم يخسر. هذا ليس مؤتمرَ وحدة… هذا معرضُ جزرٍ منعزلة.']]},
{h:'م٣ · داخلي — أروقة المؤتمر، تكتيك الدفتر',d:'بدل إلقاء خطبة حماسية، صلاح الدين يفعل شيئاً مختلفاً: يقضي الأيام الثلاثة متنقلاً بين الوفود بدفتره — يستمع أكثر مما يتكلم، يوثق كل مشروع، ويعرّف المتشابهين ببعضهم.',dlg:[['صلاح الدين','(لقائد مشروع إغاثة) مشروعُكم لحفرِ الآبار رائع… أتعرفُ أن إخوةً من النيجرِ هنا يفعلون الشيءَ نفسَهُ ويملكون خبرةَ حفرٍ في الصخر؟ تعال أعرّفكما. (لآخر) منصتُكم التعليميةُ ممتازة، ومشروعُ الأخِ من ماليزيا يترجمُ المحتوى لعشرِ لغات — لماذا لا تتكاملان بدل أن يترجمَ كلٌّ وحده؟'],['قائد مشروع','(مندهش) أنت… لا تسوّقُ لمشروعِك؟ الجميعُ هنا يسوّقُ لنفسِه، وأنتَ تجمعُنا ببعض!'],['صلاح الدين','مشروعي أن أجمعَكم. القائدُ الذي أحملُ اسمَهُ لم يوحّدِ الأمةَ بخطبة… وحّدها بأن جلسَ مع كلِّ أميرٍ وحدَه، وأزالَ حساسيةً حساسية. أنا هنا «سمسارُ خير» — أدلُّ المخلصين بعضَهم على بعض.']]},
{h:'م٤ · داخلي — قاعة الختام، خريطة الـ٤٧',d:'ليلة ختام المؤتمر. صلاح الدين يطلب الكلمة — لا ليخطب، بل ليعرض خريطة رسمها من دفتره طوال الأيام الثلاثة.',dlg:[['صلاح الدين','(يعرض خريطة) لم أحضّرْ خطبة… حضّرتُ مرآة. طوال ثلاثةِ أيام دوّنتُ مشاريعَكم. اسمعوا الصدمة: بينكم سبعةٌ وأربعون مشروعاً… متشابهاً! سبعُ منصاتِ تعليمٍ تعملُ منفصلة، وتسعُ حملاتِ إغاثةٍ لا تعرفُ بعضَها، وستُّ مبادراتٍ للقدسِ لا تنسّقُ بينها! تخيلوا لو تكاملتْ: منصةٌ واحدةٌ بقوةِ سبع، وإغاثةٌ بذراعِ تسع. نحن لا ننقصُنا الطاقة… ينقصُنا الجسور.'],['القاعة','(صمت… ثم تصفيق يتصاعد — رأوا أنفسهم لأول مرة)']]},
{h:'م٥ · داخلي — القاعة، ميثاق الجسور',d:'صلاح الدين يطلق مبادرة ختامية تصير أساس ما سيأتي.',dlg:[['صلاح الدين','أقترحُ «ميثاقَ الجسور» بقاعدةٍ ذهبيةٍ واحدة: نتعاونُ فيما اتفقنا عليه — وهو تسعون بالمئة — ويعذرُ بعضُنا بعضاً فيما اختلفنا فيه، وهو العشرةُ الباقية. لا نطلبُ أن نتوحدَ في كلِّ شيء — هذا مستحيل. نطلبُ فقط أن نتوقفَ عن التقاتلِ في الفروع، وأن نتكاملَ في الأصول. من يوقّع؟'],['قادة المشاريع','(يتقدمون واحداً بعد آخر للتوقيع — خمسون بلداً على ميثاق واحد)'],['منظم المؤتمر','(متأثراً) عشرون سنةً ننظمُ هذا المؤتمر… وما خرجنا بشبكةٍ حقيقيةٍ إلا هذا العام. جئنا نلقي الخطب… وجاء هذا الشابُّ يبني الجسور.']],vo:'خرجتُ من إسطنبولَ لا بتصفيقٍ لخطبة… بل بشبكةِ عناوينَ من خمسين بلداً، وميثاقِ جسورٍ يجمعُهم. وستعرفون في المرحلةِ الأخيرة ماذا صنعتْ هذه الشبكة. تعلمتُ أن الأمةَ لا ينقصُها المخلصون… ينقصُها من يعرّفُ المخلصين بعضَهم ببعض. كونوا «سماسرةَ خير» يا شباب: فوحدةُ الأمةِ لا تُبنى بالشعارات… تُبنى جسراً جسراً، بين قلبين مخلصين في كلِّ مرة.'}],
msg:'الوحدة صناعة صبورة لا شعار: نتعاون فيما اتفقنا عليه ويعذر بعضنا بعضاً فيما اختلفنا فيه — والأمة لا ينقصها المخلصون بل من يعرّف المخلصين ببعضهم.',apply:'كن «سمسار خير» هذا الأسبوع: اعرف شخصين يعملان خيراً متشابهاً ولا يعرف أحدهما الآخر — واجمعهما.'},

{n:84,t:'نصفُ الدين',ic:'🏡',age:'٢١ سنة',loc:'عمّان',corner:'parents',goal:'الزواج المبكر الرشيد: اختيار ذات الدين — والبيت المسلم مشروع أمة لا حفلة',chars:['صلاح الدين','مريم','أيوب','فاطمة','أهل فاطمة'],
scenes:[
{h:'م١ · داخلي — البيت، حوار الأم',d:'قرب التخرج. مريم تفتح الموضوع بحنان أم.',dlg:[['مريم','يا صلاح الدين… أريدُ أن أفرحَ بك. بلغتَ الحاديةَ والعشرين، ولك مشروعٌ ورسالة… والزواجُ نصفُ الدين، وإعمارٌ لا تأخيرٌ للأحلام.'],['صلاح الدين','(يبتسم) ظننتُهُ يشغلُني عن الرسالة يا ماما.'],['مريم','بل يعينُك! الزوجةُ الصالحةُ نصفُ رسالتِك، لا نصفُ عبئِك. قال ﷺ: الدنيا متاع، وخيرُ متاعِها المرأةُ الصالحة. لكن اختر بعقلٍ لا بعاطفة: فاظفرْ بذاتِ الدين.'],['صلاح الدين','إذن أتعاملُ معه كما علّمتْني السلسلةُ كلُّها: وضوحُ الهدفِ أولاً — أريدُ شريكةَ رسالةٍ لا شريكةَ بيتٍ فقط. ثم سؤالُ أهلِ الثقة.']]},
{h:'م٢ · داخلي — البيت، ذكر فاطمة',d:'مريم وأيوب يستشيران أهل الثقة، فتُذكر فاطمة.',dlg:[['مريم','سألتُ الثقات… ذُكرتْ فتاةٌ اسمُها فاطمة: طالبةُ طبٍّ حافظةٌ لكتابِ الله، تديرُ ركنَ البناتِ في مقرأةِ الحي، وتشاركُ شام في المنصة! دينٌ وعلمٌ ورسالةٌ في واحدة.'],['صلاح الدين','حافظةٌ وطبيبةٌ ومربية؟ (يفكر) طبيبةٌ للأجساد… وحافظةٌ للقلوب. هذا نصفُ الرسالةِ يمشي على قدمين. لكن — العبرةُ باللقاءِ الشرعيِّ والاستخارة، لا بالوصف.'],['أيوب','بالضبط. سنرتّبُ جلسةً شرعيةً بحضورِنا — نظرةً وحديثاً عن الرؤيةِ قبل الأثاث.']]},
{h:'م٣ · داخلي — بيت أهل فاطمة، الجلسة الشرعية',d:'جلسة بحضور الأهل. حوار محترم عن الرؤية. المفاجأة: فاطمة هي من تطرح السؤال الأعمق — تختبره هو.',dlg:[['صلاح الدين','(بأدب) أبحثُ عن شريكةٍ في رسالة، لا في بيتٍ فقط. عندي مشروعٌ اسمُهُ جيلُ القدس… يأخذُ من وقتي الكثير. أريدُ من تحملُهُ معي لا من تشكو منه.'],['فاطمة','(بثقة هادئة، بحضور أهلها) وأنا عندي سؤالٌ واحدٌ يحسمُ كلَّ شيء: أين تقفُ القدسُ في بيتِك؟ لأني لا أريدُ زوجاً يعلّقُ صورتَها على الجدارِ ويكتفي… أريدُ بيتاً تكونُ القدسُ مشروعَهُ اليومي: نربّي أولادَنا عليها، وننفقُ لها، ونعدّهم جنداً لها. إن كان بيتُكَ هكذا — فأهلاً. وإن كانت مجردَ شعار — فاعذرْني.'],['صلاح الدين','(مذهول، يبتسم، ينظر لأبيه) …يا بابا، هي تختبرُني أنا! (لفاطمة) القدسُ يا فاطمة ليست على جداري… إنها على صدري. (يلمس المفتاح تحت ثوبه) وعدتُ جدي ألا أسلّمَ هذا إلا لبابِه. أبحثُ عن أمٍّ تصنعُ الجيلَ الذي يفتحُه. أظنكِ… وجدتِ جوابَك.'],['أهل فاطمة','(الأب مبتسماً) أظنُّ أن الجلسةَ… انتهت على خير!']]},
{h:'م٤ · داخلي — المسجد، عقد بسيط',d:'عقد في المسجد ووليمة بسيطة. المفاجأة الاجتماعية: أهل المخيم مدعوون في الصف الأول قبل الوجهاء.',dlg:[['صلاح الدين','(للمعترض على بساطة العرس) عمّي… زمنُ المظاهرِ أثقلَ الأعراسَ حتى عجزَ الشبابُ عن الزواج! نبيُّنا ﷺ قال: أعظمُ النكاحِ بركةً أيسرُه. وليمتُنا بسيطة… وبركتُها أن أهلَ المخيمِ فيها ضيوفُ الشرف، قبلَ أيِّ وجيه. جدي علّمني: أكرمِ الفقيرَ قبلَ الغني، فدعوتُهُ لا تُشترى.'],['كريم','(بين المدعوين، متأثراً) في عرسِكَ نجلسُ في الصفِّ الأول… ونحن أبناءُ المخيم. هذا وحدَهُ يكفي ليكونَ أبركَ عرس.']]},
{h:'م٥ · داخلي — البيت الجديد، افتتاح بركعتين',d:'بيت جديد شبه فارغ. صلاح الدين وفاطمة يفتتحانه — أول شيء: ركعتان وسجادتان متجاورتان. وأول ما يعلَّق على الجدار: خريطة القدس وصورة جبل نيبو العائلية.',dlg:[['فاطمة','(تعلّق خريطة القدس) أول ما يُعلَّق… القبلة والقضية.'],['صلاح الدين','(يعلّق صورة جبل نيبو بجانبها) وهذه صورةُ جدي يوم أرانا فلسطين من الجبل، والمفتاحُ في يده. بيتُنا يا فاطمة سيبدأ كما بدأ بيتُ أبي: بحكايةٍ وآيةٍ ودعاءٍ كلَّ ليلة. وأولُ ما يسمعُهُ أطفالُنا: الله… وأولُ ما يحبونه: رسولُ الله… وأولُ قضيةٍ يحملونها: القدس.'],['فاطمة','(تبتسم) إذن نبني بيتاً… يبني أمة. بسم الله.']],vo:'تزوجتُ باكراً ورشيداً — شريكةَ رسالةٍ لا شريكةَ بيتٍ فقط. وبدأنا بيتَنا كما بدأ أبي: على «حكايةٍ وآيةٍ ودعاء». يا شبابَ زماني: الزواجُ نصفُ الدين، والبيتُ المسلمُ مشروعُ أمةٍ لا حفلةَ ليلة. فاظفروا بذاتِ الدين… واجعلوا بيوتَكم مصانعَ أجيالٍ، لا مجردَ جدرانٍ وأثاث. فمن أحسنَ بناءَ بيتِه… بنى لبنةً في الأمة.'}],
msg:'الزواج نصف الدين والبيت مشروع أمة لا حفلة: اظفر بذات الدين شريكةَ رسالة — وابنِ بيتك على حكاية وآية ودعاء ليصير مصنع أجيال.',apply:'مهما كان عمرك: اكتب صفات «بيت المستقبل» الذي تحلم به — أي بيت؟ ما عاداته؟ ماذا يُعلق على جدرانه؟'},

{n:85,t:'براءةُ اختراعِ النور',ic:'💡',age:'٢١ سنة',loc:'مختبر الجامعة',corner:'academy',goal:'الابتكار وقفاً: العلم يبلغ كماله حين يوهب — سنة الوقف العلمي تعود',chars:['صلاح الدين','الأستاذ المشرف','ممثلا شركتين','كريم','فاطمة'],
scenes:[
{h:'م١ · داخلي — المختبر، شرارة الفكرة',d:'استرجاع قصير: ليلة عتمة في المخيم أثناء درس لجيل القدس — الأطفال يحفظون على ضوء الهاتف لأن الكهرباء مقطوعة. عودة للحاضر: صلاح الدين في المختبر يطور مشروع تخرجه — نظام إنارة شمسية منخفض الكلفة للمساجد والمدارس البعيدة عن الشبكة.',dlg:[['صلاح الدين','(للأستاذ) الفكرةُ وُلدتْ في المخيم يا دكتور: أطفالٌ يحفظون القرآنَ على ضوءِ هاتف. قلتُ: إن كانت الشمسُ تشرقُ على الجميع مجاناً… فلماذا يبقى الفقراءُ في العتمة؟ نظامٌ شمسيٌّ رخيصٌ بسيطُ التركيب، لكلِّ مسجدٍ ومدرسةٍ بعيدةٍ عن الشبكة.']],vo:'أجملُ الاختراعاتِ يا أصدقائي تولدُ من وجعٍ حقيقي، لا من ترفِ المختبرات. ولدَ اختراعي من عينَي طفلٍ يحفظُ آيةَ النورِ… في العتمة.'},
{h:'م٢ · داخلي — المختبر، البحث الصبور',d:'مونتاج المختبر: فشل، قياس، إعادة معايرة، ليالٍ طويلة. فاطمة (زوجته الآن) تعينه بحساباتها الدقيقة. النظام يعمل أخيراً — كلفة منخفضة وكفاءة عالية.',dlg:[['فاطمة','(تراجع الأرقام معه) الكفاءةُ ممتازة، والكلفةُ نصفُ الأنظمةِ التجارية! هذا سيضيءُ آلافَ المدارس.'],['الأستاذ المشرف','(يفحص النتائج) صلاح الدين… هذا ليس مشروعَ تخرج. هذا اختراعٌ قابلٌ للتسجيل. سنتقدمُ ببراءة.']]},
{h:'م٣ · داخلي — المختبر، البراءة والعرضان',d:'النظام يُمنح براءة تسجيل. شركتان تعرضان شراءها بمبلغ يغني شاباً في مقتبل عمره.',dlg:[['ممثل الشركة الأولى','نشتري البراءةَ بمبلغٍ يجعلُكَ ثرياً — ونصنّعُهُ تجارياً.'],['ممثل الشركة الثانية','بل نحن نعرضُ أكثر — حقوقٌ حصريةٌ عالمية.'],['صلاح الدين','(يستمع بهدوء، ينظر لفاطمة… ثم يبتسم) شكراً لكما. لكن عندي عرضٌ لا يخطرُ ببالِكما: لن أبيعَها لأحد. سأقفُها.'],['ممثل الشركة','(مصدوم) تقفُها؟! مبلغٌ كهذا… ترفضُهُ لتعطيَ اختراعَكَ مجاناً؟!'],['صلاح الدين','ليس مجاناً — بل لله. سأنشرُ المخططاتِ مفتوحةً لكلِّ جمعيةٍ خيريةٍ في العالم: تصنعُها بنفسِها وتضيءُ بها فقراءها. لن يملكَها أحد… فيملكُها الجميع.']]},
{h:'م٤ · داخلي — المختبر، درس الوقف',d:'الأستاذ المشرف يستغرب القرار، فيشرح صلاح الدين مستحضراً تاريخ الوقف.',dlg:[['الأستاذ','قرارُكَ نبيلٌ لكنه… غريبٌ في زمنِنا. من يرفضُ ثروةً مقابلَ فكرة؟'],['صلاح الدين','غريبٌ اليومَ يا دكتور… مألوفٌ في تاريخِنا! أجدادُنا أوقفوا العلمَ كلَّه: المستشفياتُ التي تعالجُ مجاناً، والأسبلةُ التي تسقي الظمآن، والمكتباتُ المفتوحة، ومدارسُ توقفُ عليها القرى. العلمُ عندنا يا دكتور يبلغُ كمالَهُ لا حين يُباع… بل حين يُوهَب. أنا فقط أعيدُ سنةً نسيناها. هذا اختراعي… ووقفي.'],['الأستاذ','(متأثراً)… علّمتَني اليومَ درساً في مادةٍ لا تُدرَّسُ في كليةِ الهندسة.']]},
{h:'م٥ · خارجي — مسجد المخيم، النور يُوقَف',d:'أول تركيب: مسجد المخيم الذي بدأت منه الفكرة. مساءً، يُشغَّل النظام لأول مرة — المسجد يضيء ليلة كاملة بلا انقطاع. كريم عند المفتاح الكهربائي، والأطفال يحفظون تحت النور. لوحة صغيرة على الجدار.',dlg:[['كريم','(يضغط المفتاح، النور يملأ المسجد — يبكي) ليلةٌ كاملةٌ من النور… لأول مرة! الأطفالُ سيحفظون دون أن ينطفئَ الضوء. (يقرأ اللوحة) «وقفٌ لله — على روحِ عبد القادر، حاملِ المفتاح». يا صلاح الدين… سمّيتَهُ باسمِ جدك؟'],['صلاح الدين','(متأثراً) جدي أوقفَ عمرَهُ سراً للمخيم… فليكن أولُ نورٍ أوقفُهُ باسمِه. صدقتُهُ الجاريةُ تُضيءُ الآن — يصلُهُ أجرُها في قبرِه، ويحفظُ على ضوئِها الأطفال. هكذا لا يموتُ الصالحون.'],['طفل يحفظ تحت النور','(بصوت عالٍ) اللهُ نورُ السماواتِ والأرض…'],['صلاح الدين','(يبتسم ودمعته تلمع) آيةُ النور… تحت النور. اكتملتِ الدائرة.']],vo:'رفضتُ ثروةً… وربحتُ نوراً يُوقَفُ لله في آلافِ المساجدِ حول العالم. تعلمتُ أن العلمَ كالثمرة: إن أكلتَها وحدَك فنيتْ، وإن زرعتَها أطعمتِ الأجيال. أوقفوا علمَكم ومالَكم وجهدَكم يا شباب… فالوقفُ يدٌ تعملُ لكم وأنتم في قبورِكم. وأعظمُ ما تملكون… ليس ما تجمعون، بل ما تُبقونه يعملُ من بعدِكم.'}],
msg:'العلم يبلغ كماله حين يُوهب لا حين يُباع: أوقف علمك ومالك — فالوقف يد تعمل لك وأنت في قبرك، وهكذا لا يموت الصالحون.',apply:'أوقف شيئاً اليوم مهما صغر: كتاباً في مكتبة المسجد، كرة للحارة، مصحفاً — وانوِ أجره الجاري.'},

{n:86,t:'عودةٌ إلى مانشستر',ic:'🔁',age:'٢١ سنة',loc:'مانشستر — مسجد النور',corner:'social',goal:'ثمرة الصبر الدعوي: توم يصير طه — والوفاء يطوي القارات ليشهد السجدة الأولى',chars:['صلاح الدين','الشيخ إدريس','توم/طه','فاطمة'],
scenes:[
{h:'م١ · داخلي — المقر، رسالة الشيخ إدريس',d:'صلاح الدين يفتح بريده فيجد رسالة من الشيخ إدريس (شاخ الآن) — قصيرة غامضة.',dlg:[['صلاح الدين','(يقرأ) «إلى صلاحِ الدين — يا من كنتَ أسدَنا الصغير: تعالَ إلى مانشستر متى استطعت. لديّ أمانةٌ لا تُسلَّمُ إلا بيدِك، ولا تُروى في رسالة. تعالَ… واحضرْ قلبَك». (يرفع رأسه لفاطمة) الشيخ إدريس… بعد إحدى عشرةَ سنة. أمانة؟ لا أفهم — لكن قلبي يدقُّ. نسافر.'],['فاطمة','(تبتسم) رجلٌ يستدعيكَ بهذه الكلماتِ بعد كلِّ هذه السنين… لا يُرَد. جهّزْ حقيبتَك — أنا معك.']],vo:'رسالةٌ غامضةٌ من الرجلِ الذي فتحَ لي بابَ المسجدِ أولَ مرةٍ وأنا في الرابعة. «أمانةٌ لا تُروى في رسالة». سافرتُ إلى مانشستر بعد إحدى عشرةَ سنة… وقلبي يعرفُ أن شيئاً كبيراً ينتظرني. ولم أكن أعلمُ أنه أجملُ ثمرةٍ في حياتي كلِّها.'},
{h:'م٢ · خارجي — شوارع مانشستر، جولة الحنين',d:'صلاح الدين وفاطمة في شوارع مانشستر. المطر نفسه، البيوت نفسها. يقف أمام بيت طفولته القديم، ثم عند سور حديقة آل ويلسون — حيث سأله توم يوماً «من هو الله؟».',dlg:[['صلاح الدين','(يلمس السور) هنا… على هذا السورِ بالضبط، سألني جاري توم وأنا في السادسة: من هو الله؟ وأجبتُهُ بلعبةِ «من صنعها؟». (يبتسم بحنين) وهنا أهديتُهُ أولَ مصحفٍ مترجم يومَ سافرنا. أين أنتَ الآن يا توم؟'],['فاطمة','(تنظر للبيت المجاور) وهذا بيتُهم؟ ما زالوا هنا؟'],['صلاح الدين','لا أعرف… انقطعتْ رسائلُنا منذ سنتين حين انشغلتُ بالجامعة. آخرُ ما كتبَه: «بدأتُ أقرأُ عن دينِكَ بجدية». وأنا… قصّرتُ في متابعته. (بحسرة) يا ليتني ما انقطعت.']]},
{h:'م٣ · داخلي — مسجد النور، اللقاء',d:'مسجد النور — اتسع وتجمّل. الشيخ إدريس (شيخ مسنّ الآن) يستقبل صلاح الدين بحضن طويل، ثم يقوده إلى قاعة فيها جمع ينتظر.',dlg:[['الشيخ إدريس','(يحتضنه) أسدُنا الصغير… صارَ أسداً كبيراً يقودُ جيلاً! تابعتُ أخبارَك من بعيد وأنا أبكي فخراً. والآن — الأمانةُ التي دعوتُكَ لها. (يشير لرجل يقف مبتسماً بين الجمع، في يده مصحف)'],['صلاح الدين','(ينظر للرجل… يتجمد… ملامح مألوفة كبرت) …توم؟! توم! أنت هنا؟!'],['توم','(بعينين دامعتين) بل… انتظرْ حتى تسمعَ اسمي الجديد يا صديقي. الشيخُ إدريس أصرَّ ألا يتمَّ الأمرُ إلا بحضورِك.']]},
{h:'م٤ · داخلي — مسجد النور، الشهادتان',d:'ذروة السلسلة العاطفية. توم يجلس أمام الجمع، صلاح الدين بجانبه ويده على كتفه، والشيخ إدريس يلقنه. المسجد يحبس أنفاسه.',dlg:[['توم','(بصوت يرتجف ثم يثبت) بعد إحدى عشرةَ سنةً من الرسائل… وقراءةِ المصحفِ الذي أهديتَني… وزياراتي لهذا المسجد… قررت. (ينظر لصلاح الدين) أردتُ أن تكونَ أنتَ الشاهد — يا من فتحتَ لي البابَ بصحنِ كعكٍ وأنت في الرابعة. (يلتفت للشيخ، يرفع سبابته) أشهدُ أن لا إلهَ إلا الله… وأشهدُ أن محمداً رسولُ الله.'],['المسجد','(ينفجر بالتكبير — الله أكبر تهز الجدران — وصلاح الدين يعانق توم وكلاهما يبكي بلا حياء)'],['صلاح الدين','(بين دموعه) الحمدُ لله… الحمدُ لله! يا رب… دعوتُ لك في كلِّ ليلةِ قدرٍ منذ الطفولة! استجابَ اللهُ… بعد ثمانِ عشرةَ سنةً من صحنِ الكعك!']]},
{h:'م٥ · داخلي/خارجي — المسجد ثم المقبرة، طه',d:'توم يختار اسمه الجديد، ثم يزوران معاً قبر السيدة ويلسون التي رحلت.',dlg:[['توم','اختَرتُ اسمي: طه. (لصلاح الدين) لأن أولَ ما أحببتُ من دينِكم… نبيٌّ اسمُهُ طه، حدثتْني عنه رسائلُك يومَ سألتُكَ «من هو محمد عندكم؟». أتذكرُ جوابَك؟ ما زلتُ أحفظُه.'],['صلاح الدين','(متأثراً) طه… أهلاً بك في دينِ الله يا أخي. (يزوران القبر)'],['طه','(عند قبر أمه) أمي رحلتْ قبلَ أن تراني أُسلم… لكنها في أواخرِ أيامِها أوصتْني بوصيةٍ عجيبة: «الزمْ أصدقاءَ طفولتِكَ الطيبين — ذلك الصبيُّ العربيُّ وأهلُه، كانوا خيرَ جيرانٍ عرفناهم». كأنها كانت تعرف.'],['صلاح الدين','(يضع يده على كتفه) أمُّكَ أطعمَتْها أمي من عقيقتي يومَ وُلدت… وأنتَ اليومَ أخي في الله. سبحانَ من يكتبُ الحكاياتِ من أولِها. ادعُ لها — فبرُّها بجيرانِها كان من أسبابِ هدايتِك.']],vo:'صحنُ كعكٍ في الرابعة… وسؤالٌ على سورٍ في السادسة… ومصحفٌ مترجمٌ يومَ الوداع… وستون رسالة… وثمانيَ عشرةَ سنةً من الدعاء. ثم — طه. يا من تدعو لهدايةِ أحدٍ فتيأس: البذورُ الصادقةُ لا تموتُ أبداً… بعضُها فقط يزهرُ بعد ثمانيَ عشرةَ سنة. لا تحتقروا صحنَ كعكٍ صغيراً… فقد يفتحُ قلباً، وقلبٌ يفتحُ… باباً إلى الجنة.'}],
msg:'البذور الصادقة لا تموت بل تزهر متأخرة: ثمانية عشر عاماً بين صحن الكعك والشهادتين — فلا تحتقر معروفاً صغيراً، ولا تيأس من هداية أحد دعوتَ له.',apply:'لا تستعجل ثمار دعوتك: أحسن اليوم إلى شخص بعيد عن الدين إحساناً صامتاً — وادعُ له باسمه في سجودك.'},

{n:87,t:'يوسفُ وشام',ic:'🌱',age:'٢١ سنة',loc:'عمّان',corner:'parents',goal:'التربية تتوارث: الأخ الأكبر مربٍّ ثانٍ — وثمرة البيت الواحد تتعدد أشكالها',chars:['يوسف','شام','صلاح الدين','أيوب','مريم'],
scenes:[
{h:'م١ · خارجي/داخلي — افتتاحية بصوت جديد',d:'حلقة مبتكرة: الراوي يتغير لأول مرة! يوسف (١٧) وشام (١٤) يرويان بالتناوب. يوسف عند حمام سباحة يدرّب صغاراً، وشام في استوديو ركن البنات تصور قصة.',dlg:[['يوسف (راوياً)','(يصفّر لفريق السباحة) أنا يوسف — أخو صلاح الدين الأصغر بأربع سنوات. كلُّكم سمعتم قصته… أما اليومَ فأحكي لكم القصةَ التي لا يحكيها هو: كيف صنعنا نحن — أنا وشام — على يديه، دون أن يلقيَ علينا محاضرةً واحدة.'],['شام (راوية)','(أمام الكاميرا) وأنا شام — سُمّيتُ على بلادِ الشام. أصغرُ بسبعِ سنين. تذكرون الرضيعةَ التي حرسَها الأخوان؟ ها أنا أحرسُ اليومَ جيلاً من الصغيرات.']],vo:'(بصوت صلاح الدين، مقاطعاً بمحبة) دعوني هذه المرةَ أصمت… فأجملُ ما يُقالُ عن المربي، يقولُهُ من رباهم. اسمعوهما.'},
{h:'م٢ · داخلي — مونتاج الطفولة بعيون جديدة',d:'مونتاج مشاهد من حلقات سابقة — لكن من زاوية يوسف وشام: يوسف الرضيع الغيور الذي علّمه صلاح الدين «الأخ الحامي»، شام المولودة التي حُرست، الديناصور الذي أهداه، البطانية الزرقاء المتوارثة.',dlg:[['يوسف (راوياً)','لم يجلسْني أخي يوماً ويقل: «كن قوياً، احفظِ القرآن». لا. كنتُ أراهُ يستيقظُ للفجرِ فأستيقظ. أراهُ يسبحُ حتى يتقن فأتقن. أراهُ يعلّمُ الصغارَ بصبرٍ فأتعلمُ الصبر. التربيةُ يا أصدقائي عدوى… لا محاضرة.'],['شام (راوية)','وأنا؟ رأيتُ أمي تحكي القصصَ للصغار، ورأيتُ أخي يحوّلُها منصة… فقلت: ولماذا لا أحكي أنا للصغيرات؟ لم يطلبْ مني أحد — فقط رأيتُ الطريقَ ممهداً بأقدامِهم فمشيت.']]},
{h:'م٣ · داخلي — إنجازات الصف الثاني',d:'عرض إنجازاتهما: يوسف يقود فريق سباحة، حفظ عشرين جزءاً، ويدير عمود الرياضة في جيل القدس. شام أطلقت «رياض الجيل» لتعليم الصغيرات، وقصصها المصورة تصل الآلاف.',dlg:[['يوسف','عشرون جزءاً — سأكملُ الثلاثين هذا العام كما وعدتُ جدي عند فراشِه. وفريقي فازَ ببطولةِ الناشئين… بنفسِ قاعدةِ أخي: البطلُ من يسبقُ نفسَه.'],['شام','و«رياضُ الجيل» فيه الآن ثلاثون معلمةً صغيرة! نصنعُ جيلَ الأمهاتِ القادمات — فأمي علّمتني أن الأمَّ الواحدةَ تربّي أمة.'],['صلاح الدين','(يشاهدهما بفخر) وعدَنا جدي أن نكونَ مربّين ثلاثتَنا… وها نحن: مهندسٌ، وسباحٌ حافظ، ومعلمةُ صغيرات. ثلاثُ ثمراتٍ من بيتٍ واحد — كلٌّ بلونِه.']]},
{h:'م٤ · داخلي — البيت، قاعدة القدوة الصامتة',d:'العائلة مجتمعة. حوار عن سر التربية.',dlg:[['يوسف','(لأبيه) بابا… ما سرُّكم؟ كيف خرجنا ثلاثتُنا على هذا الطريق دون أن تجبرونا؟'],['أيوب','لأننا لم نجبرْكم… أريناكم. القدوةُ الصامتةُ يا يوسف أبلغُ من ألفِ موعظة. أمُّكم ما قالتْ «احفظوا» — فتحتِ المصحفَ كلَّ فجرٍ وأنتم ترون. وأنا ما قلتُ «صلّوا في المسجد» — مشيتُ إليه في الثلجِ وأخذتُ صلاحَ الدينَ بيدي. الأطفالُ يفعلون ما نفعلُ… لا ما نقول.'],['مريم','ثم إن صلاحَ الدينَ صار قدوتَكما الثانية. الأخُ الكبيرُ مربٍّ يا يوسف — شئتَ أم أبيت، إخوتُكَ الصغارُ يرونك.']]},
{h:'م٥ · داخلي — مجلس التقاعد المبتسم',d:'مجلس عائلي. الوالدان يعلنان — بابتسامة — «تقاعدهما» التربوي.',dlg:[['أيوب','(مبتسماً) يا أولادي… أنا وأمُّكم نعلنُ اليومَ تقاعدَنا! (ضحك) مهمتُنا الأولى اكتملت: ثلاثتُكم صرتم مربّين — تصنعون أجيالاً كما صنعناكم. الآن دورُكم أنتم.'],['مريم','ربّينا ثلاثة… فصار كلُّ واحدٍ منهم يربّي مئات. هذه بركةُ التربيةِ الصالحة: تبدأ بواحدٍ فتصيرُ نهراً.'],['صلاح الدين','(يقبّل يد أمه ورأس أبيه) ما تقاعدتُما يا والديّ… بل تضاعفتُما. كلُّ طفلٍ نعلّمُهُ حسنةٌ في ميزانِكما، وكلُّ جيلٍ نبنيهِ امتدادٌ لبيتِكما. البيتُ الواحدُ الصالح… يصيرُ مدرسةَ أجيال.'],['يوسف وشام','(معاً) وعهدُنا: نربّي كما رُبّينا.']],vo:'(بصوت صلاح الدين) هذه المرةُ الوحيدةُ التي تركتُ فيها الحكايةَ لغيري… لأن أصدقَ شهادةٍ على المربي، يقولُها من رباهم. يا أهلَ البيوت: لا تربّوا أطفالَكم بالكلام… ربّوهم بالمشهد. كونوا القدوةَ التي تُرى، لا الصوتَ الذي يُسمَع. فالبيتُ الواحدُ الصالح — كبيتِ أبي — قد يصيرُ منارةً تضيءُ لأجيالٍ لم تولدْ بعد.'}],
msg:'التربية عدوى لا محاضرة: الأطفال يفعلون ما نفعل لا ما نقول — والبيت الواحد الصالح يصير مدرسة أجيال، والأخ الكبير مربٍّ شاء أم أبى.',apply:'أنت قدوة شئت أم أبيت: اختر عادة حسنة واثبت عليها أسبوعاً كاملاً أمام إخوتك بلا كلمة وعظ واحدة — وراقب العدوى.'},

{n:88,t:'خطبةُ التخرج',ic:'🎤',age:'٢١ سنة',loc:'مدرج الجامعة',corner:'academy',goal:'الكلمة أمانة المنابر الكبرى: خطاب يلخص الرحلة ويوجه جيلاً — الخطابة ذروة إعداد بدأ في التاسعة',chars:['صلاح الدين','فاطمة','أيوب','مريم','آلاف الخريجين'],
scenes:[
{h:'م١ · داخلي — غرفته، قصاصة المنبر الأول',d:'صلاح الدين يتخرج بمرتبة الشرف، واختير لإلقاء كلمة الخريجين أمام آلاف. في غرفته، يخرج من محفظته قصاصة ورق قديمة صفراء.',dlg:[['فاطمة','ما هذه الورقةُ القديمة؟'],['صلاح الدين','(يفردها بحنان) خطبتي الأولى… منبرُ الناشئةِ في مسجدِ النور، وأنا في التاسعة. دقيقتان، وركبتاي ترتجفان، ونسيتُ نصفَها فارتجلتُ قصةَ المزهرية! احتفظتُ بها اثنتَي عشرةَ سنة. (يبتسم) من ذلك المنبرِ الصغير… إلى مدرجٍ فيه آلاف. الطريقُ طويل يا فاطمة.'],['فاطمة','والشيخ إدريس قال لك يومَها: «سيكون لك مع الكلمةِ شأن، وستقفُ على منابرَ أكبر». صدق.']]},
{h:'م٢ · داخلي — البيت، بروفة أمام أصدق النقاد',d:'صلاح الدين يتدرب على خطبته أمام عائلته — أصدق جمهور. أيوب ومريم ويوسف وشام وفاطمة.',dlg:[['صلاح الدين','(يتدرب) …تعلمنا لنبنيَ لا لنغادر…'],['أيوب','(مقاطعاً بحنان — كما فعل في خطبة التاسعة) جميلة… لكن أين حكايتُك؟ الناسُ تنسى المواعظَ وتحفظُ الحكايات — القاعدةُ التي علّمتُكَ إياها ونسيتَ سطرَك على المنبر الأول.'],['صلاح الدين','(يضحك) لن أنساها ثانيةً يا بابا! سأحكي رحلتي: من طفلٍ في مانشستر إلى هنا. الحكايةُ الصادقةُ… أبلغُ من كلِّ الشعارات.'],['شام','(مازحة) وهذه المرةَ لن أصفّقَ في منتصفِ الجملةِ كما كنتُ أفعلُ وأنا رضيعة!']]},
{h:'م٣ · داخلي — المدرج، افتتاح يفاجئ',d:'مدرج الجامعة الضخم، آلاف الخريجين وأهاليهم. صلاح الدين يعتلي المنصة — لا يبدأ بالبروتوكول المعتاد.',dlg:[['صلاح الدين','(يبدأ) بسمِ الله، والحمدُ لله، والصلاةُ على رسولِ الله. (البروتوكول الرسمي يتوقف لحظة — ثم يستمر) أساتذتي، زملائي، أهلي… قبل إحدى عشرةَ سنةً هبطتْ بي طائرةٌ في هذا البلد، طفلاً في العاشرة، لا يكادُ لسانُهُ ينطقُ الفصحى — كان الصفُّ يضحكُ من لكنتي. واليومَ أقفُ خطيبَ دفعتي. لم يتغير ذكائي… تغيّرَ دفترٌ أخضرُ وثلاثُ كلماتٍ في اليوم. فلا ييأسْ منكم أحد.']]},
{h:'م٤ · داخلي — المدرج، نص الخطبة المحوري',d:'ذروة الخطبة — تُعرض شبه كاملة، جملها تصلح شعارات للسلسلة كلها. المدرج مأخوذ.',dlg:[['صلاح الدين','يا خريجي اليوم: اسمعوا كلمةً واحدة — تعلمنا لنبنيَ، لا لنغادر. شهادتُكَ التي تحملُها اليومَ ليست تذكرةَ سفرٍ تهربُ بها من أمتِك… إنها عقدُ عملٍ توقّعُهُ معها! أمةٌ علّمتِ الدنيا الطبَّ والفلكَ والهندسةَ يومَ كان غيرُها في ظلام… لا يليقُ بأبنائها أن يكونوا خدماً في مصانعِ غيرهم وبيوتُهم خراب. لا أقولُ لا تطلبوا العلمَ في الخارج — بل تعلموا من كلِّ الدنيا، ثم عودوا فابنوا. القدسُ لن تُحرَّرَ بالدموعِ ولا بالخطب… بل بجيلٍ يتقنُ ويتراحمُ ويستعد — جيلٍ يبني نفسَهُ ليستحقَّ النصرَ قبل أن يطلبَه. كونوا هذا الجيل. الأمةُ لا تنتظرُ عباقرة… تنتظرُ مخلصين أتقنوا ما بأيديهم. أتقنوا صنعتَكم… تكونوا لبناتٍ في جدارِها. وابدؤوا اليوم — لا بعد التخرج، اليوم.'],['المدرج','(صمت مأخوذ… ثم تصفيق يقف له الآلاف)']]},
{h:'م٥ · داخلي — المدرج، طوفان التسجيل',d:'صلاح الدين يختم بدعوة عملية. بعد الخطبة، طابور طويل من الخريجين يسجلون في قافلة بناء تنطلق بعد شهر.',dlg:[['صلاح الدين','(يختم) ولأني لا أحبُّ الكلامَ بلا عمل: بعد شهرٍ تنطلقُ «قافلةُ بنّائين» إلى قرى الأطرافِ المنسية — إعمارٌ وطبٌّ وتعليم. من أرادَ أن يترجمَ شهادتَهُ عملاً من اليوم الأول… فليسجّلْ عند الباب. لا تنتظروا وظيفة… ابدؤوا رسالة.'],['خريج','(يسجل) كلمتُكَ غيّرتْ قراري — كنتُ سأسافرُ الأسبوعَ القادم. سأؤجلُ… وأبدأُ بالقافلة.'],['فاطمة','(تحصي الأسماء ليلاً، مذهولة) ثلاثمئة متطوعٍ في ليلةٍ واحدة! خطبةٌ واحدة…'],['صلاح الدين','(يبتسم) ليست الخطبةُ يا فاطمة… الصدق. من منبرِ الناشئةِ تعلمتُ: احكِ ما عشتَ لا ما حفظت — والكلمةُ الصادقةُ جيش.']],vo:'من دقيقتين على منبرِ ناشئةٍ نسيتُ نصفَهما… إلى خطبةٍ سجّلَ بعدها ثلاثمئةُ شابٍّ في قافلةِ بناء. اثنتا عشرةَ سنةً من إعدادِ الكلمة، بدأتْ بحكايةِ مزهرية. يا شبابَ زماني: الكلمةُ أمانةٌ ومسؤولية — قل خيراً أو اصمت، وإذا قلتَ فأتقنْ واصدُق. فالكلمةُ الصادقةُ المتقنة… تبني جيوشاً من المتطوعين، والكلمةُ الجوفاء تُنسى قبل أن يجفَّ حبرُها.'}],
msg:'تعلمنا لنبني لا لنغادر: شهادتك عقد عمل مع أمتك لا تذكرة سفر عنها — والكلمة الصادقة المتقنة جيش، فاحكِ ما عشت لا ما حفظت.',apply:'اكتب خطبة تخرجك أنت مسبقاً — نعم الآن: ماذا تريد أن تقول للناس يوم تكتمل دراستك؟ احتفظ بها لذلك اليوم.'},

{n:89,t:'قافلةُ البنّائين',ic:'🧱',age:'٢١ سنة ونصف',loc:'قرى الأطراف — الأردن',corner:'social',goal:'العمل الجماعي الضخم الأول: من نادي حي إلى قافلة إعمار — الإدارة بالشورى والأمانة المالية المطلقة',chars:['صلاح الدين','المتطوعون','المقاول المحلي','أهل القرية','العصبة'],
scenes:[
{h:'م١ · خارجي — نقطة الانطلاق، القافلة تتحرك',d:'فجر. حافلات تصطف، ثلاثمئة متطوع — مهندسون وأطباء وطلاب — يحملون العدة والمعدات. مشهد انطلاق ملبّى بالتكبير. صلاح الدين يقف على درجة الحافلة.',dlg:[['صلاح الدين','(للمتطوعين) شهرٌ كاملٌ في قرى الأطرافِ المنسية: نرممُ مدرسةً ومسجداً، نحفرُ بئرين، ونطبّبُ من لا يصلُهُ طبيب. قاعدتُنا الوحيدة: جئنا خَدَماً لا مُنعِمين. من جاء يبحثُ عن صورةٍ أو منّةٍ… فليبقَ هنا. ومن جاء لله… فليركبْ بسم الله!'],['المتطوعون','(تكبير جماعي والحافلات تتحرك)']],vo:'من صندوقِ كعكٍ في مانشستر… إلى حديقةِ حيٍّ في عمّان… إلى قافلةٍ من ثلاثمئةِ بنّاء. المشروعُ نفسُهُ يا أصدقائي كبرَ معي: القاعدةُ لم تتغير — ابدأ صغيراً واثبت، فيكبرُ الصغيرُ نهراً. واليومَ… حان وقتُ أكبرِ اختبارٍ في القيادة.'},
{h:'م٢ · خارجي — معسكر القافلة، نظام الشورى والمال',d:'المعسكر منظم كخلية. صلاح الدين يرسّخ نظام إدارة إسلامي: مجلس شورى صباحي كل يوم، ولوحة كبيرة عند مدخل القرية تعرض كل دينار (الوارد والمصروف) مكشوفاً للجميع.',dlg:[['متطوع','لماذا نعرضُ كلَّ قرشٍ على لوحةٍ يراها الجميع؟ ألا يكفي أن نكونَ أمناء؟'],['صلاح الدين','الأمانةُ لا تكفي وحدَها يا أخي — يجبُ أن تُرى. المالُ العامُّ نارٌ إلا بالحساب المكشوف. حين يرى أهلُ القريةِ والمتطوعون كلَّ دينارٍ أين ذهب… لا يبقى مجالٌ لشكٍّ ولا وسوسةٍ ولا شبهة. الشفافيةُ تحمي العملَ وتحمينا نحن. جدي علّمني الصدقةَ الخفية… والشيخُ إدريس علّمني أن المالَ العامَّ يُعلَن.'],['صلاح الدين','(في شورى الصباح) ولن أقررَ وحدي شيئاً — كلُّ قرارٍ يمرُّ على المجلس. القائدُ الذي يستبدُّ… يخذلُهُ الله.']]},
{h:'م٣ · خارجي — القرية، أزمة المقاول',d:'عقبة تكاد تفشل القافلة: مقاول محلي متضرر — يرى في العمل التطوعي تهديداً لرزقه — يشكو للسلطات ويحرّض. مواجهة محتملة.',dlg:[['المقاول','(غاضباً) تأتون بعملِكم «المجاني» فتقطعون رزقي! أنا مقاولُ هذه المنطقةِ من عشرين سنة! سأشتكيكم!'],['متطوع','(همساً لصلاح الدين) نطردُهُ؟ نتجاهلُه؟ هو يعرقلُنا!'],['صلاح الدين','(يفكر — يتذكر إسطنبول: نكسب الخصم لا نخاصمه) لا. تعالَ معي. (للمقاول، بهدوء) عمّي، معك حق — لم نقصدْ أن نضرَّ رزقَك. عندي عرض: نستأجرُ معداتِكَ الثقيلةَ لكلِّ القافلة، ونوظفُ عمالَكَ بأجرٍ في مشاريعِنا. تكسبُ أنتَ… ونكسبُ نحن خبرتَك ومعرفتَكَ بالمنطقة. الخيرُ يتسعُ للجميع — لماذا نتخاصمُ ونحن نريدُ الشيءَ نفسَه: عمارةَ بلدِك؟'],['المقاول','(يتغير وجهه من الغضب للدهشة)… تستأجرُ مني بدل أن تطردَني؟ توظفُ عمالي؟ (يصمت)… أنا جئتُ أخاصمُكم فعرضتم عليّ شراكة. (يمد يده) معكم — ومعداتي وعمالي تحتَ أمرِكم، نصفُ الأجرِ تبرعٌ مني للقرية!']]},
{h:'م٤ · خارجي — القرية، مونتاج الإعمار',d:'مونتاج شهر العمل: مدرسة تُصبغ وتُرمم (متطوعون ومعدات المقاول معاً)، بئران تتدفقان، عيادات متنقلة يعمل فيها الأطباء، أطفال القرية يساعدون بحماس، صلاح الدين يحمل الطوب مع العمال (القائد يخدم أكثر).',dlg:[['متطوع','(يرى صلاح الدين يحمل الطوب رغم أنه القائد) أنتَ القائد! دعِ الحملَ لنا!'],['صلاح الدين','(يحمل ويبتسم) القائدُ الذي أحملُ اسمَهُ كان آخرَ من يأكلُ وأولَ من يعمل. ونبيُّنا ﷺ نقلَ الترابَ في الخندقِ حتى وارى الترابُ بطنَه. القائدُ يخدمُ أكثر يا أخي… ولا يأكلُ حتى يأكلَ الجميع.']]},
{h:'م٥ · خارجي — القرية، الوداع وبذرة جديدة',d:'نهاية الشهر. أهل القرية يودعون القافلة بالدموع. مدرسة تلمع، ماء يتدفق، وقبل الرحيل: صلاح الدين يؤسس «فرع جيل القدس» في القرية — يترك أثراً باقياً لا زيارة عابرة.',dlg:[['مختار القرية','(متأثراً) جاءتْنا وفودٌ كثيرةٌ عبر السنين… تصوّرُ وترحل. أنتم وحدَكم عملتُم كأبنائِنا، وكشفتُم مالَكم كأنكم متهمون، وأشركتُم مقاولَنا بدل أن تُقصوه. لن ننساكم.'],['صلاح الدين','(يسلّم شاباً من القرية دفتراً) وحتى لا ننساكم نحن أيضاً: هذا «فرعُ جيلِ القدس» في قريتكم — حلقةُ قرآنٍ ونادٍ وعملُ خيرٍ شهري. لا نريدُ أن نبنيَ لكم ونرحل… نريدُ أن تبنوا أنتم من بعدِنا. اليدُ العليا يا شباب… أن تصنعَ أياديَ عُلْيا أخرى.'],['المقاول','(يودعه) علّمتَني في شهرٍ ما لم أتعلمْهُ في عشرين سنة: أن الخيرَ يتسعُ للجميع. سأكونُ أولَ الداعمين لفرعِكم هنا.']],vo:'شهرٌ واحدٌ في قرى الأطراف… علّمني إدارةَ أمةٍ مصغرة: شورى تجمعُ العقول، وأمانةٌ ماليةٌ مكشوفة، وخصمٌ نكسبُهُ لا نخاصمُه، وقائدٌ يخدمُ أكثرَ ولا يستأثر. وأثمنُ درس: لا تبنِ للناسِ وترحل… علّمهم أن يبنوا. اليدُ العليا الحقيقيةُ يا أصدقائي… ليست التي تعطي، بل التي تصنعُ أيادي مُعطيةً من بعدها.'}],
msg:'اليد العليا تصنع أيادي عُليا أخرى: القائد يخدم أكثر ويكشف كل دينار ويكسب خصمه لا يخاصمه — ولا تبنِ للناس وترحل بل علّمهم أن يبنوا.',apply:'شارك في عمل تطوعي جماعي هذا الشهر (يوم واحد يكفي) — وطبق قاعدة: اخدم أكثر وتكلم أقل.'},

{n:90,t:'عهدُ المئةِ ألف',ic:'🤝',age:'٢١ سنة ونصف',loc:'المقر — بث مباشر للعالم',corner:'quds',goal:'خاتمة مرحلة البناء: الحركة تصير جيلاً عالمياً — تجديد العهد الجماعي نحو الهدف الكبير',chars:['صلاح الدين','العصبة','طه (من لندن)','قادة الفروع العالمية'],
scenes:[
{h:'م١ · داخلي — المقر، جردة الست سنوات',d:'مقر جيل القدس — كبر وتطور. على الجدار خريطة عالم مضيئة: نقاط في أربعين بلداً. صلاح الدين والعصبة يستعدون لبث مباشر تاريخي.',dlg:[['معاذ','(ينظر للخريطة) ست سنوات… من أربعةِ فتيانٍ على سطحِ بيتِ الجد… إلى أربعين بلداً. كيف حدثَ هذا؟'],['صلاح الدين','ميثاقُ الجسورِ من إسطنبول، والمنصةُ التي وصلتِ المليون، والقوافل. لم نبنِ إمبراطوريةً يا معاذ — بنينا شبكةَ إخوةٍ مخلصين، كلٌّ في بلدِه، يجمعُهم هدفٌ واحد. الأربعةُ الصادقون صاروا مئةَ ألف… لأننا ما طلبنا أن نقودَ الكل، بل أن نوصلَ الكلَّ ببعضِهم.'],['حمزة','واليوم… مئةُ ألفٍ يجددون العهدَ معاً في بثٍّ واحد!']]},
{h:'م٢ · داخلي — المقر، كواليس البث',d:'استوديو بسيط — تطور قليلاً عن البطانيات، لكن ما زال متواضعاً. شاشات متعددة تعرض الفروع حول العالم تنتظر. قلوب مشتعلة رغم بساطة التقنية.',dlg:[['شام','(الآن ١٤، تدير الجانب التقني بثقة) كلُّ الفروعِ متصلة! جاكرتا جاهزة، لاجوس جاهزة، سراييفو، لندن، القاهرة، غزة… والعدّادُ يتخطى المئةَ ألف متصلٍ مباشر!'],['صلاح الدين','(يأخذ نفساً، يلمس المفتاح على صدره) بسم الله. يا رب… من سطحِ بيتِ جدي إلى العالم. اجعلْها خالصةً لوجهك.']]},
{h:'م٣ · داخلي — البث، مشاهد العواصم',d:'البث يبدأ. الكاميرا تتنقل بين الشاشات — فروع جيل القدس حول العالم، لغات شتى وعهد واحد.',dlg:[['قائد جاكرتا','(بالإندونيسية ثم العربية) من إندونيسيا… عشرةُ آلافِ فتىً يجددون العهد!'],['قائد لاجوس','(من نيجيريا) من غربِ إفريقيا… معكم!'],['طه','(من لندن — توم سابقاً، يقود فرع مانشستر ولندن) من بريطانيا… حيثُ بدأتْ قصةُ صلاحِ الدينِ بصحنِ كعك! نحنُ هنا — والحمدُ للهِ الذي هداني لأكونَ من هذا الجيل!'],['أبناء عمومة كريم','(من غزة، وسط الركام لكن بعيون مشتعلة) من غزة… من قلبِ الجرح… جيلُ القدسِ حاضر! نحن الأقربُ إليها… ولن نتخلف!'],['صلاح الدين','(يبتلع دمعته أمام الكاميرا) يا الله… أرى الأمةَ في شاشةٍ واحدة. طه من لندن، وأهلُ غزة، وإندونيسيا، ونيجيريا، والبوسنة… لغاتٌ شتى، وعهدٌ واحد.']]},
{h:'م٤ · داخلي — البث، رفع المفتاح',d:'لحظة الذروة الرمزية. صلاح الدين يقود تجديد العهد الجماعي — «عهد المئذنة» بصيغته الجماعية — ثم يرفع مفتاح الجد أمام العدسة.',dlg:[['صلاح الدين','(للعالم) يا جيلَ القدس في كلِّ أرض… نجددُ عهدَنا معاً، أعيدوه خلفي بكلِّ ألسنتِكم: نتقنُ أعمالَنا… (يردد العالم) نتراحمُ فيما بيننا… (يردد العالم) نبني أنفسَنا وأجيالَنا… (يردد العالم) ونستعدُّ ليومٍ تُفتَحُ فيه الأبواب. (يرفع المفتاح الحديدي أمام الكاميرا — مئة ألف عين تراه) هذا مفتاحُ بيتِ جدي في القدس، حملَهُ سبعين سنةً وسلّمنيهِ على جبلِ نيبو. أقولها لكم كما قالها لي: حين يجهزُ الجيلُ الذي يستحقُّ النصر… تُفتَحُ الأبواب. والجيلُ — بفضلِ الله — يجهز. أراهُ أمامي الآن في مئةِ ألفِ وجه.'],['مئة ألف (عبر الشاشات)','(تكبير عالمي متداخل بكل اللغات)']]},
{h:'م٥ · داخلي — المقر، تمهيد النهاية',d:'البث ينتهي. الاستوديو يفرغ، العصبة وحدها. صلاح الدين يقف أمام خريطة العالم المضيئة، المفتاح في يده. لحظة تأمل هادئة — قطع أسود يمهد للمرحلة الأخيرة.',dlg:[['كريم','(يقف بجانبه) أتذكرُ يا صلاح الدين… فتىً في مخيمٍ يبيعُ الكعك، أريتَهُ مفتاحاً يشبهُ مفتاحَ جدي؟ اليومَ ذلك الفتى يقودُ فرعاً، وأبناءُ عمومتِهِ في غزةِ يجددون العهد. من كان يصدق؟'],['صلاح الدين','(ينظر للخريطة) اللهُ يصدق. الذي بدأ بأربعةٍ على سطح… بلغَ بنا مئةَ ألف. لكن يا كريم — (يلمس المفتاح، وجهه يجدّ) هذا كلُّهُ كان الإعداد. الجيلُ جهز. والوعدُ اقترب.'],['كريم','كم بقي؟'],['صلاح الدين','(ينظر بعيداً، يهمس)… بقيتْ أربعُ سنواتٍ على عيدي الخامسِ والعشرين. (قطع أسود)']],vo:'ست سنوات بعد سطحِ بيتِ جدي… صار جيلُ القدسِ شبكةً في أربعين بلداً، ومئةَ ألفِ قلبٍ يجددون العهدَ في نَفَسٍ واحد. اكتملتْ مرحلةُ البناء. جهّزْنا الجيلَ الذي يستحقُّ النصر… كما وحّدَ صلاحُ الدينِ الأولُ الأمةَ قبل أن يرفعَ سيفَه. وبقيتْ أربعُ سنواتٍ فقط… على أعظمِ فصولِ الحكاية. اقلبوا الصفحةَ معي — المرحلةُ الأخيرة: الفجرُ الكبير.'}],
msg:'حين يجهز الجيل الذي يستحق النصر تُفتح الأبواب: الأربعة الصادقون صاروا مئة ألف حين وصلنا المخلصين ببعضهم — نتقن ونتراحم ونبني ونستعد.',apply:'جدد عهدك الشخصي الليلة (الذي كتبته في حلقة عهد المئذنة) — واقرأه هذه المرة على أحد تحبه ليشهد عليك.'}
]});
